function draw(){let w=1000,h=520;ctx.clearRect(0,0,w,h);let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,current.id==='ocean'?'#164766':current.id==='robot'?'#383255':'#16373f');grad.addColorStop(1,current.id==='ocean'?'#4b9b9d':current.id==='robot'?'#8c8b91':'#6c9c86');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);if(current.id==='stars'){for(let i=0;i<35;i++){let x=(i*163+45)%1000,y=(i*79+13)%290;ctx.globalAlpha=.4+.3*Math.sin(i+t);ctx.fillStyle='#fff6cc';ctx.beginPath();ctx.arc(x,y,i%4===0?2.5:1.3,0,7);ctx.fill();}ctx.globalAlpha=1;ctx.fillStyle='#f7e9b1';ctx.beginPath();ctx.arc(790,96,36,0,7);ctx.fill();ctx.fillStyle='#254b52';ctx.beginPath();ctx.arc(804,82,32,0,7);ctx.fill();}else{ctx.strokeStyle='#ffffff25';for(let i=0;i<16;i++){ctx.beginPath();ctx.arc((i*157)%1000,((i*67-t*13)%550+550)%550,8+i%5*5,0,7);ctx.stroke();}}hill('#193f46',380,70);hill(current.id==='ocean'?'#245b68':'#396f60',435,90);ctx.fillStyle=current.id==='ocean'?'#baab77':'#9aa881';ctx.beginPath();ctx.ellipse(500,435,225,40,0,0,7);ctx.fill();if(current.id==='stars'){ctx.save();ctx.translate(495,428);ctx.rotate(-.06);ctx.fillStyle='#d5b3a0';ctx.fillRect(-98,-17,196,37);ctx.strokeStyle='#b3837f';for(let i=-90;i<100;i+=20){ctx.beginPath();ctx.moveTo(i,-17);ctx.lineTo(i,20);ctx.stroke();}ctx.restore();}let active=current.lines.find(l=>t>=l[0]&&t<=l[1]);character(340,370,current.id==='robot'?'🤖':current.id==='ocean'?'🐢':'🦊',active?.[2]===0,0);character(660,370,current.id==='robot'?'👩‍🌾':current.id==='ocean'?'🐠':'🐰',active?.[2]===1,1);ctx.font='45px serif';ctx.textAlign='center';ctx.fillText(current.id==='stars'?'🧁':current.id==='robot'?'🌷':'🐚',500,420);if(active){ctx.font='500 17px sans-serif';const name=current.roles[active[2]].split(',')[0];ctx.fillStyle='#f4f0dd';ctx.fillText(name+' parle…',500,65);}else if(t===0){ctx.font='500 15px sans-serif';ctx.fillStyle='#e8f5e5';ctx.fillText('Une petite histoire à jouer avec ta voix',500,60);}}
function hill(color,y,depth){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,y);ctx.bezierCurveTo(200,y-depth,350,y+depth,550,y-15);ctx.bezierCurveTo(750,y-depth,850,y-35,1000,y);ctx.lineTo(1000,520);ctx.lineTo(0,520);ctx.fill();}
function character(x,y,emoji,speaks,i){let bounce=speaks?Math.sin(t*10)*5:Math.sin(t*1.5+i)*2;ctx.fillStyle='#102a3345';ctx.beginPath();ctx.ellipse(x,y+50,65,15,0,0,7);ctx.fill();if(speaks){ctx.strokeStyle=i?'#b8edb0':'#cabaff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x,y-7,81,89,0,0,7);ctx.stroke();}ctx.font='132px "Segoe UI Emoji",sans-serif';ctx.textAlign='center';ctx.fillText(emoji,x,y+30+bounce);ctx.font='600 14px sans-serif';ctx.fillStyle='#f5f5e8';ctx.fillText(current.roles[i].split(',')[0],x,y+78);}
